:root {
  color-scheme: light;
  font-family: system-ui, sans-serif;
  font-size: 16px;
  color: #183443;
  background: #dce9d3;
}

* { box-sizing: border-box; }
body {
  min-height: 100vh;
  margin: 0;
  padding: 28px 16px;
  display: grid;
  place-items: center;
  background: radial-gradient(circle at 50% 10%, #f4f0d5, #dce9d3 65%);
}
.game-card {
  width: min(100%, 620px);
  padding: clamp(20px, 5vw, 38px);
  border: 4px solid #183443;
  border-radius: 12px;
  background: #fffdf2;
  box-shadow: 9px 9px 0 #183443;
}
header { text-align: center; }
.eyebrow, .hint, .square-readout {
  font-size: .82rem;
  font-weight: 800;
  letter-spacing: .09em;
  text-transform: uppercase;
}
.eyebrow { margin: 0 0 6px; color: #39806b; }
h1 { margin: 0; font-size: clamp(1.8rem, 7vw, 2.7rem); line-height: 1.1; }
h1 span { color: #d7654b; }
.intro { margin: 10px 0 24px; color: #536a70; }
.board-wrap { max-width: 450px; margin: 0 auto; }
.board {
  display: grid;
  grid-template-columns: repeat(6, 1fr);
  border: 3px solid #183443;
  background: #183443;
  gap: 3px;
}
.cell {
  position: relative;
  aspect-ratio: 1;
  min-width: 0;
  padding: 5px;
  display: flex;
  flex-direction: column;
  justify-content: space-between;
  background: #f2d98b;
  font-size: clamp(.68rem, 2.8vw, 1rem);
  font-weight: 800;
}
.cell:nth-child(4n+2), .cell:nth-child(4n+3) { background: #e9c76e; }
.cell.start { background: #a9d6a2; }
.cell.finish { background: #f1aa69; }
.cell .marker { font-size: clamp(1rem, 4vw, 1.5rem); line-height: 1; align-self: flex-end; }
.cell .token {
  position: absolute;
  left: 50%; top: 52%;
  transform: translate(-50%, -50%);
  width: 24px; height: 24px;
  display: grid; place-items: center;
  border: 2px solid #fffdf2;
  border-radius: 4px;
  background: #d7654b;
  color: white;
  box-shadow: 2px 2px 0 #183443;
  font-size: 15px;
  z-index: 1;
}
.controls { max-width: 450px; margin: 22px auto 0; display: flex; align-items: center; justify-content: space-between; gap: 16px; }
.square-readout { color: #536a70; }
.square-readout strong { margin-left: 5px; color: #183443; font-size: 1.35rem; }
.message { min-height: 1.5em; margin: 5px 0 0; font-weight: 650; }
button {
  flex: 0 0 auto;
  min-height: 52px;
  padding: 0 22px;
  border: 3px solid #183443;
  border-radius: 7px;
  background: #39806b;
  color: white;
  font: inherit;
  font-weight: 800;
  cursor: pointer;
  box-shadow: 4px 4px 0 #183443;
  transition: transform .12s, box-shadow .12s, background .12s;
}
button:hover { background: #2e6c5b; }
button:focus-visible { outline: 4px solid #d7654b; outline-offset: 4px; }
button:active { transform: translate(3px, 3px); box-shadow: 1px 1px 0 #183443; }
button:disabled { cursor: default; opacity: .72; }
.hint { margin: 19px 0 0; text-align: center; color: #71837b; }
@media (max-width: 420px) {
  body { padding: 16px 12px; }
  .game-card { padding: 20px 14px; box-shadow: 6px 6px 0 #183443; }
  .cell { padding: 3px; }
  .controls { align-items: flex-start; }
  button { padding: 0 15px; }
}

const board = document.querySelector('#board');
const positionLabel = document.querySelector('#position');
const message = document.querySelector('#message');
const rollButton = document.querySelector('#roll');

const ladders = new Map([[3, 11], [8, 17], [20, 27]]);
const snakes = new Map([[14, 5], [24, 16], [29, 22]]);
let position = 1;

// Rows snake back and forth: square 1 begins at the lower left.
for (let index = 0; index < 30; index++) {
  const row = Math.floor(index / 6);
  const offset = index % 6;
  const square = row % 2 === 0 ? row * 6 + offset + 1 : row * 6 + (6 - offset);
  const cell = document.createElement('div');
  cell.className = 'cell';
  cell.setAttribute('role', 'gridcell');
  cell.dataset.square = String(square);
  cell.setAttribute('aria-label', `Square ${square}`);
  if (square === 1) cell.classList.add('start');
  if (square === 30) cell.classList.add('finish');
  const number = document.createElement('span');
  number.textContent = String(square);
  cell.append(number);
  const destination = ladders.get(square);
  const snakeEnd = snakes.get(square);
  if (destination || snakeEnd) {
    const marker = document.createElement('span');
    marker.className = 'marker';
    marker.textContent = destination ? '🪜' : '🐍';
    marker.setAttribute('aria-hidden', 'true');
    cell.append(marker);
  }
  board.append(cell);
}

function renderToken() {
  board.querySelector('.token')?.remove();
  const cell = board.querySelector(`[data-square="${position}"]`);
  const token = document.createElement('span');
  token.className = 'token';
  token.textContent = '●';
  token.setAttribute('aria-hidden', 'true');
  cell.append(token);
  cell.setAttribute('aria-label', `Square ${position}, your token`);
}

rollButton.addEventListener('click', () => {
  const roll = Math.floor(Math.random() * 6) + 1;
  const next = position + roll;
  if (next > 30) {
    message.textContent = `You rolled ${roll}. You need an exact roll to reach 30.`;
    return;
  }

  position = next;
  let result = `You rolled ${roll}.`;
  if (ladders.has(position)) {
    result += ` Ladder! Climb to ${ladders.get(position)}.`;
    position = ladders.get(position);
  } else if (snakes.has(position)) {
    result += ` Snake! Slide to ${snakes.get(position)}.`;
    position = snakes.get(position);
  }
  positionLabel.textContent = String(position);
  if (position === 30) {
    message.textContent = `${result} You win! 🎉`;
    rollButton.disabled = true;
  } else {
    message.textContent = result;
  }
  renderToken();
});

renderToken();
